    yamlCode:
      '# Production multi-level aggregation with reliability\ninput:\n  kafka:\n    addresses: [ "kafka-broker-1:9092", "kafka-broker-2:9092" ]\n    topics: [ "sensor-events" ]\n    consumer_group: "aggregation-pipeline"\n\nrate_limit_resources:\n  - label: input_limit\n    local:\n      count: 100000\n      interval: 1s\n\npipeline:\n  processors:\n    - rate_limit:\n        resource: input_limit\n    - try:\n        - mapping: |\n            root = if !this.exists("sensor_id") {\n              throw("Missing sensor_id")\n            } else if this.temperature < -50 || this.temperature > 100 {\n              throw("Temperature out of range")\n            } else {\n              this\n            }\n            root.processing_instance = "aggregation-instance-1"\n    - catch:\n        - log:\n            level: WARN\n            message: "validation failed: ${! error() }"\n        - mapping: root = deleted()\n    - archive:\n        format: json_array\n    - mapping: |-\n        root = this.map_each(event -> [\n          event.merge({"aggregation_type":"multi_level","aggregation_level":"sensor","group_key":event.sensor_id+"|sensor","window_duration_minutes":1}),\n          event.merge({"aggregation_type":"multi_level","aggregation_level":"location","group_key":event.location+"|location","window_duration_minutes":1}),\n          event.merge({"aggregation_type":"multi_level","aggregation_level":"global","group_key":"global","window_duration_minutes":1})\n        ]).flatten()\n    - unarchive:\n        format: json_array\n    - group_by_value:\n        value: ${! this.group_key }\n    - mapping: |-\n        let events = json().from_all().sort_by(event -> event.timestamp)\n        let first = $events.index(0)\n        let values = $events.map_each(event -> event.temperature)\n        let end = meta("window_end_timestamp").ts_parse("2006-01-02T15:04:05Z07:00").ts_unix_nano() / 1000000000\n        let minute = env("WINDOW_MINUTE_SECONDS").or("60").number()\n        root = if batch_index() == 0 {\n          {"aggregation": {\n            "aggregation_type": $first.aggregation_type,\n            "aggregation_level": $first.aggregation_level,\n            "group_key": $first.group_key,\n            "sensor_id": $first.sensor_id,\n            "location": $first.location,\n            "window_start": ($end - $minute * $first.window_duration_minutes).ts_format("2006-01-02T15:04:05Z07:00"),\n            "window_end": meta("window_end_timestamp"),\n            "window_duration_minutes": $first.window_duration_minutes,\n            "event_count": $events.length(),\n            "temperature_avg": ($values.sum() / $values.length() * 100).round() / 100,\n            "temperature_min": $values.min(),\n            "temperature_max": $values.max(),\n            "sensor_count": $events.map_each(event -> event.sensor_id).unique().length(),\n            "location_count": $events.map_each(event -> event.location).unique().length()\n          }}\n        } else { deleted() }\n\noutput:\n  fallback:\n    - http_client:\n        url: "https://analytics.company.com/aggregations"\n        retries: 5\n        batching:\n          count: 500\n          period: "10s"\n    - file:\n        path: "/var/buffer/aggregations.jsonl"\nbuffer:\n  system_window:\n    size: ${WINDOW_MINUTE:1m}\n    timestamp_mapping: root = this.timestamp\n',
